fn keep_bigger_than(mut v: Vec<Int>, limit: Int) -> Int {
    let mut total = 0
    let mut i = 0
    while i < v.len() {
        let x = v[i]
        i = i + 1
        if x > limit {
            total = total + x
            drop x
        }
    }
    drop total
    drop v
}

